select.where:

             and received_seq = #{receivedSeq}
             and healthcode_log_id = #{healthcodeLogId}
             and unique_id = #{uniqueId}
             and dept_name like concat(concat('%', #{deptName}), '%')
             and person_name like concat(concat('%', #{personName}), '%')
             and channel_code = #{channelCode}
             and scene_face_image = #{sceneFaceImage}
             and scene_iris_image = #{sceneIrisImage}
             and scene_face_score = #{sceneFaceScore}
             and scene_iris_score = #{sceneIrisScore}
             and stock_face_image = #{stockFaceImage}
             and stock_iris_image = #{stockIrisImage}
             and match_mode = #{matchMode}
             and match_score = #{matchScore}
             and checklive_score = #{checkliveScore}
             and checklive_result = #{checkliveResult}
             and result = #{result}
             and time_used = #{timeUsed}
             and face_time_used = #{faceTimeUsed}
             and iris_time_used = #{irisTimeUsed}
             and temperature = #{temperature}
             and temperature_floor = #{temperatureFloor}
             and temperature_top = #{temperatureTop}
             and device_sn = #{deviceSn}
             and device_model = #{deviceModel}
             and device_name like concat(concat('%', #{deviceName}), '%')
             and device_ip = #{deviceIp}
             and device_longitude = #{deviceLongitude}
             and device_dimension = #{deviceDimension}
             and device_direction = #{deviceDirection}
             and server_id = #{serverId}
             and batch_date = #{batchDate}
             and tenant_id = #{tenantId}
             and temperature_result = #{temperatureResult}

				and received_time >= to_date(#{beginTime},'yyyy-MM-dd HH24:mi:ss')


				and received_time <= to_date(#{endTime},'yyyy-MM-dd HH24:mi:ss')


				AND (log.dept_id = #{deptId} OR log.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE FIND_IN_SET (#{deptId},ancestors)  <>  0 ))


			${params.dataScope}

mapper.select:

         INNER JOIN (
		  SELECT unique_id as unique_id_tmp, MAX(received_time) AS received_time_tmp
		  FROM person_faceiris_match_log
		   where tenant_id = #{tenantId}
		  GROUP BY unique_id
		) AS tmp
		ON log.unique_id = tmp.unique_id_tmp AND log.received_time = tmp.received_time_tmp

